"إقفال الشهر: «المالية» ← «إقفال الشهور» ← اختار الشهر ← «فحص». الفحص بيقولك اللي فاضل (مسودات، قيود مستندها اتغيّر، مستندات ما اتقيّدتش، مصروفات أو بنزين أو تقارير أو خصومات لسه مستنية، كشف رواتب ما اتعتمدش، أيام خزينة ما اتجردتش، شهر قبله لسه مفتوح). صلّح كل نقطة، وافحص تاني، ولما يطلع نظيف دوس «إقفال الشهر». الشهر المقفول ما يتسجلش فيه حاجة؛ لو لازم، أعد فتح آخر شهر مقفول بسبب.": "Month close: \"Finance\" ← \"Month Close\" ← choose the month ← \"Check\". The check tells you what's left (drafts, entries whose document changed, unposted documents, pending expenses, fuel, reports or deductions, an unapproved payroll, uncounted treasury days, an earlier month still open). Fix each point, check again, and when it's clean press \"Close Month\". Nothing can be recorded in a closed month; if needed, reopen the last closed month with a reason.",
