"الأعمار لليوم أياً كانت الفترة: ما يسلّمه السائق يسدد أقدم كاش معه أولاً، فالباقي معه هو الأحدث. غير المعتمد لا يُعمَّر. الرصيد الموجب عليه للشركة، والسالب له عند الشركة ويحتاج تسوية. التحصيل والخزينة والإيداعات للفترة؛ والخزينة لكل فرع ومشتركة بين شركاته فلا يطبق عليها فلتر الشركة.": "Aging is as of today regardless of period: what the driver hands in settles their oldest cash first, so what remains is the newest. Unapproved amounts aren't aged. A positive balance is owed by them to the company; a negative one is owed to them and needs settlement. Collection, treasury and deposits are for the period; treasury is per branch and shared between its companies, so the company filter doesn't apply to it.",
