"التطبيق لا يُثبَّت من متجر: نزّل ملف APK من آخر بناء في CI، ارفعه هنا، ثم «نشر». يقرأ النظام اسم الحزمة ورقم الإصدار (versionCode) من الملف نفسه، ويرفض تطبيقاً آخر أو رقماً ليس أعلى من آخر إصدار منشور. يطلب أندرويد من السائق تأكيد التثبيت دائماً: لا يمكن التثبيت الصامت لتطبيق من خارج المتجر.": "The app isn't installed from a store: download the APK from the latest CI build, upload it here, then \"Publish\". The system reads the package name and version number (versionCode) from the file itself, and rejects a different app or a number not higher than the latest published version. Android always asks the driver to confirm installation: silent install isn't possible for an app outside the store.",
