"الحقل": "Field",
"الحقول تُعرف هنا لا في الكود: اليومية يملؤها السائق في التطبيق مع لقطة شاشته، والشهرية يدخلها المكتب أو يستوردها في بيانات الشهر. قواعد نظام الدفع تقرأ منها (مثلاً سعر لكل وحدة من حقل عددي، أو شرط على حقل نعم/لا). مجموع الحقل اليومي في الشهر: جمع الأرقام، أو عدد الأيام بنعم.": "Fields are defined here, not in code: daily ones are filled by the driver in the app with their screenshot, and monthly ones are entered or imported by the office in the month data. Payment system rules read from them (e.g. a rate per unit of a numeric field, or a condition on a yes/no field). A daily field's monthly total: sum of numbers, or count of Yes days.",
"الحل": "Resolution",
"الحوادث": "Accidents",
"الحوادث الواقعة في الفترة (عدا الملغاة)؛ وقائمة «بانتظار محضر الشرطة» تشمل كل المفتوحة أياً كان تاريخها. حتى سنة.": "Accidents occurring in the period (excluding cancelled); the \"Awaiting police report\" list includes all open ones regardless of date. Up to one year.",
"الخدمات": "Services",
"الخدمات الخارجية التي يتصل بها النظام. كل تغيير يُسجَّل في سجل التدقيق، والمفاتيح لا تُعرض بعد حفظها.": "External services the system connects to. Every change is logged in the audit log, and keys are not shown after saving.",
