"الخزينة تنقص أيضاً بالمصروف المدفوع منها وبالسلف عند اعتمادها، وترجع عند إلغاء المصروف.": "Treasury also decreases with expenses paid from it and advances when approved, and is restored when the expense is cancelled.",
