"الخطوة تنطبق على المستند الذي يبلغ مبلغها. المستند يمر بالخطوات بالترتيب، ولا يعتمد شخص واحد خطوتين، والرفض دائماً بسبب. الطلبات الجارية تكمل بخطواتها.": "A step applies to documents that reach its amount. A document passes through the steps in order, one person can't approve two steps, and rejection always needs a reason. Requests in progress continue with their steps.",
