"الزر يفتح شاشة من التطبيق فقط (لا روابط خارجية). بدون نص يظهر نص التطبيق الافتراضي بلغة السائق.": "The button opens a screen in the app only (no external links). Without text, the app's default text shows in the driver's language.",
"الزرار بيظهر بس لو فيه إصدار من التطبيق منشور (الإعدادات ← تحديثات التطبيق).": "The button shows only if an app version is published (Settings ← App Updates).",
