"السائق المسؤول": "Responsible driver",
"السائق المسؤول من سجل التسليم وقت الحادث؛ لا تُسجّل المسؤولية دون محضر الشرطة، ولا يُخصم قبل اعتماد تقدير الأضرار": "The responsible driver comes from the handover log at the time of the accident; liability isn't recorded without a police report, and nothing is deducted before the damage estimate is approved",
"السائق بلا شركة يختار من التطبيق أول مرة «أنت شغال مع أنهي شركة؟». حتى الموافقة يرى حقول تقرير الشركة التي اختارها، والرواتب لا تحسبه عليها. الموافقة تضع شركته ومعرّفه فيها.": "A driver without a company picks \"Which company do you work with?\" in the app the first time. Until approved, they see the report fields of the company they picked, and payroll doesn't count them under it. Approval sets their company and ID in it.",
"السائق سجّل العربية من التطبيق بقراءة عدادها وصورته؛ العهدة تبدأ بالموافقة": "The driver registered the car from the app with its odometer reading and photo; custody starts on approval",
"السائق لم يدخلها: من الفاتورة، لحساب الاستهلاك (لا تغيّر المبلغ)": "Not entered by driver: from the invoice, for consumption calculation (doesn't change the amount)",
