"السائقون بلا هاتف يدخلون مرة واحدة برقمهم المدني وكلمة مرور مبدئية، ثم يسجلون هواتفهم برمز واتساب": "Drivers without a phone log in once with their Civil ID and an initial password, then register their phones with a WhatsApp code",
"السائقون على رأس العمل؛ من معه سيارة يرجّعها أو تتبدّل في نفس الخطوة": "Drivers on duty; anyone with a car returns it or swaps it in the same step",
