"الشهر المقفول ما يتسجلش فيه قيد ولا حركة كاش بتاريخ فيه. يُقفل الشهر بعد ما يخلص، وبعد الشهور اللي قبله، ولما الفحص يطلع نظيف. آخر شهر مقفول بس هو اللي يتفتح تاني بسبب.": "No entry or cash transaction dated in a closed month can be recorded. A month is closed after it ends, after the months before it, and when the check is clean. Only the last closed month can be reopened, with a reason.",
