"الطلب يذهب من السائق أو المكتب للمركز المختار مباشرة؛ المركز يستلم السيارة ثم يجهزها بفاتورته، والسائق يؤكد الاستلام من تطبيقه. الفواتير تُعتمد هنا": "The request goes from the driver or office directly to the chosen center; the center receives the car then prepares it with its invoice, and the driver confirms pickup from their app. Invoices are approved here",
