"العقوبات لا تنزل بالشهر تحت الصفر (القرار D)": "Penalties don't take the month below zero (Decision D)",
"العقوبات لا تنزل بالشهر تحت الصفر، وما لم يُخصم يظهر «خصومات غير محصلة» للمراجعة (القرار D)": "Penalties don't take the month below zero, and anything not deducted shows as \"Uncollected deductions\" for review (Decision D)",
