"العهدة الحالية": "Current custody",
"العهدة تُصرف من خزينة فرع (تنقص الخزينة وتزيد العهدة)، ومصروفات الموظف تُسجَّل «من عهدة» فتنقص عهدته عند الاعتماد، والباقي يُرد للخزينة. في الدفاتر: حساب 1115 العهد النقدية.": "Custody is issued from a branch treasury (treasury decreases, custody increases), and the employee's expenses are recorded \"from custody\", reducing their custody on approval; the rest is returned to the treasury. In the books: account 1115 Cash custody.",
"العهدة من": "Custody from",
