"الغرض": "Purpose",
"الغي المصروف الغلط وسجّل مصروف بـ 15 واعتمده، والتوليد يعمل قيده الصح: من ح/ 5120 إلى ح/ 1110 بـ 15.": "Cancel the wrong expense, record an expense of 15 and approve it, and generation creates its correct entry: from a/c 5120 to a/c 1110 for 15.",
"الغياب والإجازات": "Absence & Leaves",
"الغياب وحده يُخصم من الراتب، وفقط إن نصّت الإعدادات على ذلك. اليوم المصنّف يُرفع من القائمة، ويمكن إلغاء التصنيف من «الأيام المصنفة».": "Only absence is deducted from salary, and only if Settings say so. A classified day is removed from the list, and the classification can be removed from \"Classified days\".",
"الفاتورة": "Invoice",
"الفترة": "Period",
"الفترة من يوم إلى": "Period from day to",
"الفحص لا يغيّر شيئاً، والتنفيذ لملف بلا أخطاء فقط ويُطبَّق كله أو لا شيء. نفس الملف يمكن استيراده مرة أخرى: يحدّث الموجود ولا يكرره.": "The check changes nothing, and running applies only to an error-free file, all or nothing. The same file can be imported again: it updates existing records without duplicating them.",
