"القالب الافتراضي (للمجموعة ولكل شركة بلا قالب خاص)": "Default template (for the group and each company without its own template)",
"القالب يُنسخ في النظام الجديد وكل قيمه قابلة للتعديل: لا سعر فيه قاعدة على الجميع.": "The template is copied into the new system and all its values are editable: no rate in it is a rule for everyone.",
