"القناة غير مفعّلة": "Channel not enabled",
"القنوات": "Channels",
"القواعد بالترتيب": "Rules in order",
"القواعد تُنفَّذ بالترتيب من الأعلى للأسفل، كل قاعدة مرة واحدة: الترتيب هو الأولوية المعتمدة (مثلاً خصم نقص التارجت قبل المكافأة أو بعدها، وتغيير السعر يحل محل السعر الأساسي أو سطر خصم منفصل). كل تعديل نسخة جديدة «يسري من شهر»، والأشهر المعتمدة لا تتغير.": "Rules run in order from top to bottom, each rule once: the order is the approved priority (e.g. target shortfall deduction before or after the bonus, and a rate change replaces the base rate or is a separate deduction line). Every edit is a new version \"effective from month\", and approved months don't change.",
"القوالب المنشورة": "Published templates",
"القيد": "Entry",
"القيد اتولّد من المستند ولسه محدش راجعه": "The entry was generated from the document and nobody has reviewed it yet",
"القيد العكسي بيلغي الغلط بالكامل، وبعده القيد الصح بالمبلغ الصح. كده المراجع شايف الاتنين ومفهوم إيه اللي حصل.": "The reversing entry cancels the mistake entirely, followed by the correct entry with the right amount. That way the reviewer sees both and understands what happened.",
"القيد العكسي تقدر تختار تاريخه (افتراضياً النهارده): مش قبل تاريخ القيد الأصلي، ومش قبل بداية الدفاتر، ومش في المستقبل، ومش في شهر مقفول.": "You can choose the reversing entry's date (today by default): not before the original entry's date, not before the books start, not in the future, and not in a closed month.",
"القيم": "Values",
