"الكاش وأعماره والخزينة": "Cash, aging & treasury",
"الكاش والخزينة": "Cash & Treasury",
"الكاشير يستلم كاش من سواق بإيصال": "The cashier receives cash from a driver with a receipt",
"الكاشير يستلم كاش من سواق بإيصال، أو سحب من البنك": "The cashier receives cash from a driver with a receipt, or a bank withdrawal",
"الكشف": "Statement",
"الكشف كله": "Whole statement",
"الكشف كما اعتُمد": "Statement as approved",
"الكشوف تُحضَّر وتُراجع وتُصدَّر عادي، لكن الاعتماد مرفوض. يفعّله مالك النظام من الإعدادات ← الرواتب بعد المطابقة.": "Statements are prepared, reviewed and exported as usual, but approval is refused. The system owner enables it from Settings ← Payroll after reconciliation.",
