"اللون بصيغة ‎#RRGGBB والأولوية رقم": "Color in ‎#RRGGBB format and priority as a number",
"اللي بيسجّل مش هو اللي بيعتمد قدر الإمكان.": "Whoever records shouldn't be whoever approves, where possible.",
"المؤشَّر يظهر للسائق. المخفي يختفي من التطبيق ويرفضه الخادم أيضاً (فلا تصل إليه نسخة قديمة أو اتصال مباشر)، وبياناته لا تُحذف: تعود كما هي عند إظهاره. يصل التغيير للسائق مع اتصال التطبيق التالي، دون تحديثه.": "Checked items show to the driver. Hidden ones disappear from the app and are also rejected by the server (so an old version or direct connection can't reach them), and their data isn't deleted: it returns as is when shown again. The change reaches the driver on the app's next connection, without updating it.",
"المادة": "Article",
"المادة 41: غياب بدون إذن أكثر من هذه الأيام المتتالية يرفع تنبيهاً لمراجعة الإجراءات القانونية. لا يُتخذ أي إجراء تلقائياً. قيم افتراضية حسب قانون العمل — راجعها مع الموارد البشرية/المستشار القانوني.": "Article 41: unexcused absence for more than this many consecutive days raises an alert to review legal procedures. No action is taken automatically. Defaults per labor law — review them with HR/legal counsel.",
"المادة 41: غياب بدون إذن أكثر من هذه الأيام في السنة يرفع تنبيهاً. قيم افتراضية حسب قانون العمل — راجعها مع الموارد البشرية/المستشار القانوني.": "Article 41: unexcused absence for more than this many days a year raises an alert. Defaults per labor law — review them with HR/legal counsel.",
