"بعد استلام المركز. القراءات بانتظار المراجعة لا تُحسب حتى تُراجع. كيلومترات GPS خطوط مستقيمة بين نقاط الهاتف فتقل عن العداد قليلاً، وكثيراً إن انقطعت الإشارة. حتى 93 يوماً.": "after the center picks it up. Readings pending review aren't counted until reviewed. GPS kilometers are straight lines between phone points, so slightly less than the odometer, and much less if the signal was lost. Up to 93 days.",
