"تبقى سيارته في عهدته أثناء الصيانة، ويعمل بالبديلة حتى يستلم سيارته: عندها تنتهي عهدة البديلة في نفس الخطوة بقراءتها وصورتها من تطبيقه. لا يحمل السائق إلا بديلة واحدة، ولا تُسلَّم البديلة لغيره قبل إرجاعها.": "Their car stays in their custody during maintenance, and they work with the replacement until they pick up their car: then the replacement's custody ends in the same step with its reading and photo from their app. A driver holds only one replacement, and it can't be handed to anyone else before it's returned.",
