"تستحق": "Due",
"تستحق الصيانة بعد عدد الأيام أو الكيلومترات من آخر مرة نُفذت، أيهما أسبق. الكيلومترات من آخر قراءة عداد مصوّرة للسيارة؛ إن لم توجد قراءة لا تُحسب ولا تُخمَّن. ساعات المحرك غير متاحة: النظام لا يستقبل بياناتها. تُنبَّه الإدارة يومياً بما يستحق قريباً أو تأخر، والطلب المنفّذ لها يسجّلها منفّذة عند استلام السيارة.": "Maintenance is due after the number of days or kilometers since it was last done, whichever comes first. Kilometers come from the car's last photographed odometer reading; without a reading they aren't counted or guessed. Engine hours aren't available: the system doesn't receive that data. Management is alerted daily of what is due soon or overdue, and the request that performs it records it as done when the car is picked up.",
