"تظهر لك تنبيهات صلاحياتك وشركاتك فقط. «تم الاطلاع» يسجّل أنك رأيته ويبقى مفتوحاً حتى يُعالج أو يزول سببه؛ كل إجراء يُحفظ في سجل التنبيه وسجل التدقيق. الأوقات بتوقيت الكويت": "You see only alerts for your permissions and companies. \"Viewed\" records that you saw it and it stays open until handled or its cause clears; every action is saved in the alert log and audit log. Times are Kuwait time",
