"قبول Evolution للرسالة يعني أنها أُرسلت للإرسال، لا أنها وصلت: إيصالات الوصول والقراءة من واتساب لا تصل للنظام. لا إعادة تلقائية لرموز الدخول (يطلبها السائق مجدداً)، وروابط التفعيل الجماعية تُعاد حتى 3 مرات.": "Evolution accepting the message means it was queued for sending, not delivered: WhatsApp delivery and read receipts don't reach the system. Login codes aren't auto-resent (the driver requests again), and bulk activation links are retried up to 3 times.",
"قبول Firebase للإشعار لا يعني ظهوره على الهاتف؛ «فُتح في التطبيق» هو الدليل على وصوله. ما لم يُرسل يُعاد تلقائياً كل 30 ثانية لمدة 48 ساعة.": "Firebase accepting a notification doesn't mean it showed on the phone; \"Opened in app\" proves delivery. Unsent ones are retried automatically every 30 seconds for 48 hours.",
