"قرار": "Decision",
"قرار التسجيل": "Registration decision",
"قرار العميل: الصافي لا ينزل تحت الصفر أبداً. ما لم يغطه المستحق من خصومات الشهر يظهر هنا بعد اعتماد الكشف «للمراجعة»، ولا يُرحّل تلقائياً. «تُرحّل للشهر التالي» تنشئ خصماً يدوياً بالمبلغ من الشهر التالي، و«إسقاط» لا يُخصم بعده شيء؛ كلاهما بملاحظة مكتوبة ولمن له صلاحية اعتماد الرواتب، ويُسجَّل في سجل التدقيق.": "Client decision: net never goes below zero. Month deductions not covered by the amount due show here after statement approval \"for review\" and are not carried over automatically. \"Carry to next month\" creates a manual deduction for the amount next month, and \"Write off\" deducts nothing further; both require a written note and payroll approval permission, and are logged in the audit log.",
