"قيم افتراضية حسب قانون العمل — راجعها مع الموارد البشرية/المستشار القانوني. الغياب بدون إذن ليس نوعاً يُطلب: يسجّله المكتب من «أيام بلا بداية يوم»، وتنبيهات المادة 41 في الإعدادات.": "Default values per the Labor Law — review them with HR/legal counsel. Absence without leave is not a type to request: the office records it from «Days without a day start», and the Article 41 alerts are in settings.",
