"كشف الرواتب المعتمد لا يتغير: «إنشاء تسوية» يفتح خصماً يدوياً للشهر القادم ويربطه بالاعتراض.": "An approved payroll statement doesn't change: \"Create Settlement\" opens a manual deduction for next month and links it to the dispute.",
"كشف الشهر من السائق": "Month statement from driver",
"كشف المنصة الشهري لكل سائق، ثم كشف الرواتب لكل شركة وشهر بأعمدة نموذجكم، والحد الأقصى للخصم وترحيل الباقي": "Monthly platform statement per driver, then the payroll statement per company and month with your template's columns, the maximum deduction and carry-over of the rest",
