"كشف كل شركة في كل شهر (المسودة قابلة للتغيير). ما لم يُخصم من قسط بسبب الحد الشهري يُرحَّل ويُستحق في الشهر التالي، فيُقرأ شهراً بشهر ولا يُجمع عبر الأشهر. حتى 24 شهراً.": "Statement per company per month (drafts can change). Any installment not deducted due to the monthly limit is carried over and due next month, so read month by month, not summed across months. Up to 24 months.",
"كشف مدفوع": "Paid statement",
"كشف معتمد": "Approved statement",
"كشف منصة بانتظار المراجعة": "Platform statement awaiting review",
"كشف واحد لكل شركة وشهر. المسودة تُعاد حسابها متى شئت، والاعتماد يعيد الحساب مرة أخيرة ثم يقفل الشهر.": "One statement per company and month. Drafts are recalculated anytime, and approval recalculates one last time then locks the month.",
