"لما الخزينة توصل للحد أو ييجي يوم الإيداع: «إيداع في البنك» برقم إيصال البنك وصورته.": "When the treasury reaches the limit or deposit day comes: \"Bank Deposit\" with the bank receipt number and photo.",
