"لن يُرسل.": "Won't be sent.",
"لنقل ما ضبطته هنا (سيرفر التجربة مثلاً) إلى نسخة أخرى (الإنتاج): القوائم والإعدادات والأدوار والمنصات وأنظمة الرواتب ودليل الحسابات وقوالب الطباعة والترجمات المنشورة. لا يحتوي الملف بيانات تشغيلية (موظفين، سيارات، عهد، مبالغ، تقارير) ولا مستخدمين أو كلمات مرور. المراجع بين الأقسام بالرموز والأسماء (رمز المنصة، رقم الحساب، السجل التجاري للشركة) لا بأرقام قاعدة البيانات.": "To move what you configured here (e.g. test server) to another instance (production): lists, settings, roles, platforms, payroll schemes, chart of accounts, print templates and published translations. The file contains no operational data (employees, vehicles, custodies, amounts, reports) nor users or passwords. References between sections use codes and names (platform code, account number, company commercial registration), not database IDs.",
"له": "owed",
"له عند الشركة": "Owed by company",
"له عند الشركة (تسوية)": "Owed by company (settlement)",
"له من هذا الشهر": "is his from this month",
"لهذا الشهر صفوف باتش من قبل: اختر «استبدال الشهر كله» ثم افحص من جديد": "This month already has batch rows: choose \"Replace whole month\" then check again",
"لهم معرّف في المنصة": "Have a platform ID",
"لو استلام كاش أو تسوية لسواق اتسجلت غلط: «الكاش والخزينة» ← «أرصدة السائقين» ← «كشف» ← «عكس» على الحركة.": "If a driver's cash receipt or settlement was recorded wrong: \"Cash & Treasury\" ← \"Driver Balances\" ← \"Statement\" ← \"Reverse\" on the transaction.",
"لو بنزين اتقبل بمبلغ غلط: اعكس حركته من كشف السواق، والطلب يرجع «بانتظار المراجعة» تقبله بالمبلغ الصح.": "If fuel was accepted with a wrong amount: reverse its transaction from the driver statement, and the request returns to \"Awaiting review\" to accept with the correct amount.",
"لو فيه ملفات باقية، اتأكد إن R2 شغالة من «اختبار الاتصال»": "If files remain, make sure R2 works via \"Test Connection\"",
"لو قفلته، الدومين الرئيسي هيوري صفحة «الصفحة مش موجودة».": "If you disable it, the main domain will show a \"Page not found\" page.",
"لو مستند اتغيّر بعد ما اتقيّد (مصروف اتلغى، فاتورة اتعدلت)، التوليد بيطلّعه في قايمة «قيود مستندها اتغيّر»: اعكس القيد القديم والتوليد الجاي يعمل الصح.": "If a document changed after posting (expense cancelled, invoice edited), generation lists it under \"Entries whose source changed\": reverse the old entry and the next generation does it right.",
