"ما يحمي الحساب: رمز واتساب على هاتف السائق، ومرة واحدة، والمدة، ومراجعة تسجيله الذاتي (ومنه الآيبان) قبل الاعتماد.": "What protects the account: WhatsApp code on the driver's phone, single use, duration, and reviewing their self-registration (including IBAN) before approval.",
"ما يحمي الحساب: مرة واحدة (السائق الحقيقي يُرفض إن سبقه أحد فيبلغكم)، والمدة، ومراجعة تسجيله الذاتي (ومنه الآيبان) قبل الاعتماد. لا رمز واتساب: اجعل المدة قصيرة.": "What protects the account: single use (the real driver is rejected if someone beats them and reports to you), duration, and reviewing their self-registration (including IBAN) before approval. No WhatsApp code: keep the duration short.",
"ما يخصمه الراتب من كل موظف: الإجمالي على أقساط شهرية متساوية، والباقي على القسط الأخير. الشهر الذي يصل حد الخصم يُرحّل باقيه للشهر التالي.": "What payroll deducts from each employee: total in equal monthly installments, remainder on the last. In a month reaching the deduction limit, the rest carries to next month.",
"ما يرسله السائق كل شهر مع لقطات الشاشة (اتركه فارغاً إن كان الشهر من التقارير اليومية)": "What the driver sends monthly with screenshots (leave empty if the month comes from daily reports)",
"ما يرسله السائق من التطبيق بعد رابط التفعيل. لا يدخل شيء في السجلات قبل الاعتماد، والاعتماد يسجّل البيانات والمستندات والعهدة معاً أو لا شيء.": "What the driver sends from the app after the activation link. Nothing enters records before approval, and approval records data, documents and custody together or nothing.",
