"ملف Excel (أي أعمدة: تختار بعد الرفع أي عمود يغذي أي حقل)": "Excel file (any columns: after upload you choose which column feeds which field)",
"ملف Excel المرفق بالعقد (السيارات، المستخدمون والسائقون، الأرصدة الافتتاحية) كما هو: نفس أسماء الأوراق ونفس الأعمدة.": "The Excel file attached to the contract (vehicles, users and drivers, opening balances) as is: same sheet names and same columns.",
"ملف Excel بصيغتكم كما هو: أوراق السيارات والموظفين بأي ترتيب أعمدة، ولو بلا صف عناوين. يقترح النظام نوع كل ورقة والعمود المناسب لكل حقل، فراجعها قبل الفحص. المستندات (الإقامة، الرخصة، الجواز) والهاتف والآيبان يكملها السائق في التسجيل الذاتي إن لم تكن في الملف. ولكل سائق إن كانت في الملف أعمدة لها: تفعيل التطبيق (نعم/لا)، وكلمة مرور مبدئية (تحتاج صلاحية «إدارة أجهزة السائقين»)، وصلاحيتها بالأيام.": "Your Excel file as is: vehicle and employee sheets in any column order, even without a header row. The system suggests each sheet's type and the matching column for each field, so review them before checking. Documents (residency, license, passport), phone and IBAN are completed by the driver in self-registration if not in the file. And per driver, if the file has columns for them: app activation (yes/no), temporary password (requires \"Manage driver devices\" permission), and its validity in days.",
"ملف Excel بورقتين: «أرصدة افتتاحية» (رصيد كل حساب يوم ما قبل بداية الدفاتر، والفرق إلى حساب الأرصدة الافتتاحية) و«قيود» (كل قيد قديم أسطره برقمه في النظام القديم). أي ورقة يمكن تركها فارغة. صف «مثال» يُتجاهل.": "Excel file with two sheets: \"Opening balances\" (each account's balance the day before the books start, difference to the opening balances account) and \"Entries\" (each old entry's lines with its number in the old system). Either sheet can be left empty. An \"Example\" row is ignored.",
