"يطلب السائق من التطبيق نظاماً آخر تعرضه منصته، ويبدأ من الشهر التالي. الموافقة تنقله من أول شهر لم تُعتمد رواتبه، والرفض يصله بسببه.": "The driver requests from the app another scheme offered by their platform, starting next month. Approval moves them from the first month without approved payroll, and rejection reaches them with its reason.",
