"يعترض السائق من التطبيق على كشف راتبه المعتمد أو على بند منه، بسبب ومرفق إن وُجد. الرد يصله بإشعار. الاعتراض لا يغيّر كشف الرواتب المعتمد: التسوية خصم يدوي لشهر قادم يُربط بالاعتراض.": "The driver disputes their approved payroll statement or an item in it from the app, with a reason and attachment if any. The reply reaches them by notification. A dispute doesn't change the approved payroll statement: settlement is a manual deduction for an upcoming month linked to the dispute.",
