"يقارن التطبيق رقم نسخته بالرقم هنا: من Firebase Remote Config إن كان Firebase مفعّلاً، وإلا من الخادم مباشرة. الحفظ ينشر الإصدار المختار إن كان مسودة ويكتب القيم في Remote Config. الإجباري يوقف شاشات النسخ الأقدم حتى تُحدَّث، والاختياري يظهر شريطاً يمكن تأجيله.": "The app compares its version number with the number here: from Firebase Remote Config if Firebase is enabled, otherwise directly from the server. Saving publishes the selected release if it's a draft and writes the values to Remote Config. Mandatory blocks older versions' screens until updated, and optional shows a postponable banner.",
