"يُسجَّل قيد معاكس بنفس المبلغ ويبقى الأصل ظاهراً في السجل. يُعكس القيد مرة واحدة فقط.": "A reversing entry for the same amount is recorded and the original stays visible in the log. An entry can be reversed only once.",
