"يُطلب منه تغييرها عند أول دخول": "They must change it at first login",
"يُطلب منه تغييرها عند الدخول التالي": "They must change it at next login",
"يُعاد الحساب مرة أخيرة ثم يُقفل الكشف وكشوف المنصات لهذا الشهر، ويصبح كشف الراتب ظاهراً لكل سائق في التطبيق.": "Recalculated one last time, then the statement and the month's platform statements are locked, and the payroll statement becomes visible to each driver in the app.",
"يُعاد فقط ما فشل؛ ما وصل لا يُرسل مرة أخرى.": "Only failures are retried; delivered ones aren't resent.",
"يُعبّأ الكارت كمصروف واحد للشركة: لا يسجّل السائق البنزين من الكاش": "The card is refilled as a single company expense: the driver doesn't record fuel from cash",
