"يُنشأ خصم يدوي بالمبلغ على السائق من الشهر التالي لشهر الكشف (أو هذا الشهر لكشف قديم)، معتمداً بقرارك. كشف الرواتب المعتمد لا يتغير.": "A manual deduction for the amount is created on the driver from the month after the statement month (or this month for an old statement), approved by your decision. The approved payroll statement doesn't change.",
